Representing a single text-editing operation, with a logical
timestamp (Module 29 lesson 3's exact Lamport clock) attached:

interface InsertOperation {
  type: 'insert';
  position: number;
  text: string;
  logicalTimestamp: number; // Module 29 lesson 3's exact mechanism
  clientId: string;
}

// THE TRANSFORM FUNCTION - the actual, genuine mathematical core of
// OT: given two CONCURRENT operations (neither caused the other),
// adjust operation B's position so applying it AFTER A still
// produces the correct, intended result
function transformInsert(opA: InsertOperation, opB: InsertOperation): InsertOperation {
  if (opA.position <= opB.position) {
    // A's insertion happened at or before B's intended position -
    // B's own position must SHIFT FORWARD by A's text length, so B's
    // text still lands where the USER actually, genuinely intended
    return { ...opB, position: opB.position + opA.text.length };
  }
  return opB; // A's insertion was genuinely AFTER B's position -
                // B's own position is unaffected, no shift needed

