// Document starts as: "Hello world"

// User A (on their own client) inserts "beautiful " at position 6:
const opA: InsertOperation = { type: 'insert', position: 6, text: 'beautiful ', logicalTimestamp: 5, clientId: 'A' };
// User A's own intended result: "Hello beautiful world"

// User B (on a DIFFERENT client) SIMULTANEOUSLY inserts "!" at
// position 11 (the end of the ORIGINAL "Hello world"), with NO
// knowledge of User A's concurrent edit:
const opB: InsertOperation = { type: 'insert', position: 11, text: '!', logicalTimestamp: 5, clientId: 'B' };
// User B's own intended result: "Hello world!"

// SCENARIO 1 - A's server receives and applies A's op first, then
// receives B's op and must transform it:
const transformedB = transformInsert(opA, opB);
// opA.position (6) <= opB.position (11), so transformedB.position
// becomes 11 + 10 ('beautiful '.length) = 21
// Applying opA then transformedB: "Hello beautiful world!" - CORRECT

// SCENARIO 2 - B's server receives and applies B's op first, then
// receives A's op and must transform it:
const transformedA = transformInsert(opB, opA);
// opB.position (11) is NOT <= opA.position (6), so transformedA is
// UNCHANGED, still position 6
// Applying opB then transformedA: "Hello beautiful world!" - SAME,
// CORRECT, CONVERGED RESULT, regardless of which order each
// server/client happened to receive and apply these two operations

