codingChallenge.solutionExample:
interface InsertOperation {
  type: 'insert';
  position: number;
  text: string;
}

interface DeleteOperation {
  type: 'delete';
  position: number;
  length: number;
}

function transformInsertAgainstDelete(deleteOp: DeleteOperation, insertOp: InsertOperation): InsertOperation {
  if (deleteOp.position + deleteOp.length <= insertOp.position) {
    // the delete happened entirely BEFORE the insert's position -
    // shift the insert's position back by the deleted length
    return { ...insertOp, position: insertOp.position - deleteOp.length };
  }
  return insertOp; // the delete happened at or after the insert's
                      // position - no shift needed
}

// VERIFICATION: 'Hello world' (11 characters)
// deleteOp: remove positions 0-6 ('Hello ') -> 'world'
// insertOp: insert '!' at position 11 (end of original string)

// ORDER 1: delete first, then transformed insert
const transformedInsert = transformInsertAgainstDelete(
  { type: 'delete', position: 0, length: 6 },
  { type: 'insert', position: 11, text: '!' }
);
// transformedInsert.position = 11 - 6 = 5
// Apply delete: 'world' (5 chars). Apply insert at position 5: 'world!' - CORRECT

// ORDER 2: insert first (at its original position), then delete
// 'Hello world' -> insert '!' at 11 -> 'Hello world!' -> delete
// positions 0-6 -> 'world!' - SAME, CONVERGED RESULT

