const notificationWorker = new Worker('user-events', async (job) => {
  if (job.name !== 'order-shipped') return;

  const { userId, orderId, trackingNumber } = job.data;

  // LESSON 1's exact shared presence state - find WHICH specific
  // socket connection(s) this user currently has open, RIGHT NOW,
  // possibly on a COMPLETELY DIFFERENT server instance than this worker
  const socketIds = await redisClient.sMembers(`sockets:${userId}`);

  if (socketIds.length === 0) {
    // user is genuinely NOT currently connected - lesson 5's exact
    // reliability concern: this event must NOT simply be lost; it
    // needs a genuine, separate delivery path (a stored notification,
    // an email) for when they next connect or check in
    await storeOfflineNotification(userId, { type: 'order-shipped', orderId, trackingNumber });
    return;
  }

  // Push DIRECTLY to every currently-open socket for this user,
  // using Module 23's exact io.to() room-based broadcasting,
  // genuinely correct even if those sockets are on OTHER instances
  // (Module 23 lesson 6's Redis adapter, now finally fully understood)
  io.to(`user:${userId}`).emit('order-update', { orderId, trackingNumber });
});

