Directly extending Module 23, lesson 2's bare reconnection handler
with THIS lesson's genuine state-recovery logic:

let lastKnownEventId: string | null = null;

socket.on('order-update', (data) => {
  lastKnownEventId = data.eventId; // track the most recent event
    // this client has GENUINELY, successfully processed
  updateUI(data);
});

socket.on('connect', async () => {
  // Module 23 lesson 2's original gap: reconnection restores the
  // CONNECTION, but the client has NO IDEA what events occurred
  // during the disconnection - THIS lesson's genuine fix:
  if (lastKnownEventId) {
    const missedEvents = await fetch(`/api/events/since/${lastKnownEventId}`).then((r) => r.json());
    // explicitly, deliberately CATCH UP on everything that happened
    // during the disconnection, in correct order, before resuming
    // genuinely live updates
    for (const event of missedEvents) {
      updateUI(event);
      lastKnownEventId = event.eventId;
    }
  }
  console.log('Reconnected and genuinely caught up');
});

