// A user's laptop goes to sleep at 2:00:00pm, with lastKnownEventId
// = 'evt-500' (the last order-update event they genuinely received
// and processed before disconnecting)

// DURING the disconnection (2:00:00pm - 2:05:00pm), TWO more
// genuine order-update events occur for this user: evt-501 and evt-502

// The laptop wakes at 2:05:00pm, and the socket's 'connect' handler fires

// WITHOUT this lesson's recovery logic (Module 23's bare reconnection):
// the client simply starts listening for NEW events again - evt-501
// and evt-502 are PERMANENTLY, SILENTLY LOST; the user's UI remains
// stuck showing evt-500's state until the NEXT genuine event arrives,
// with NO indication anything was ever missed at all

// WITH this lesson's recovery logic:
socket.on('connect', async () => {
  if (lastKnownEventId) {
    // fetches events since 'evt-500' - returns [evt-501, evt-502]
    const missedEvents = await fetch(`/api/events/since/${lastKnownEventId}`).then((r) => r.json());
    for (const event of missedEvents) {
      updateUI(event); // genuinely, explicitly catches up, IN ORDER
      lastKnownEventId = event.eventId;
    }
    // lastKnownEventId is now 'evt-502' - the client's state is
    // GENUINELY, VERIFIABLY caught up to the true, current reality
  }
});

